def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 8 or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            component = []
            touches_four = False

            while stack:
                x, y = stack.pop()
                component.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if not (0 <= nx < h and 0 <= ny < w):
                        continue
                    if grid[nx][ny] == 4:
                        touches_four = True
                    elif grid[nx][ny] == 8 and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        stack.append((nx, ny))

            if touches_four:
                for x, y in component:
                    out[x][y] = 4

    return out
